import 'dart:async';import 'dart:math';import 'dart:typed_data';import 'package:flutter/foundation.dart';/// Privacy Layer — Traffic analysis resistance (Req 12)./// - Pads all messages to fixed 512 bytes (Req 12.1)/// - Random relay delay 100–2000ms (Req 12.2)/// - Dummy packet transmission every ~30s (Req 12.3)/// - No plaintext headers in forwarded blobs (Req 12.4)class PrivacyLayer {  static const int _paddedSize = 512;  static const int _minDelayMs = 100;  static const int _maxDelayMs = 2000;  static const int _dummyIntervalSeconds = 30;  final _rng = Random.secure();  Timer? _dummyTimer;  // Callback for sending dummy packets via BLE  void Function(Uint8List dummyPacket)? onSendDummy;  bool _enabled = true;  bool get isEnabled => _enabled;  void setEnabled(bool v) {    _enabled = v;    if (!v) _stopDummies();  }  /// Start periodic dummy packet transmission (Req 12.3)  void startDummies() {    _stopDummies();    _dummyTimer = Timer.periodic(      Duration(seconds: _dummyIntervalSeconds + _rng.nextInt(15)),      (_) => _emitDummy(),    );    debugPrint('[PrivacyLayer] Dummy packet schedule started');  }  void _stopDummies() {    _dummyTimer?.cancel();    _dummyTimer = null;  }  /// Pad plaintext data to exactly 512 bytes (Req 12.1).  /// Format: [originalLen (2 bytes big-endian)] [data] [random padding]  Uint8List pad(Uint8List data) {    if (!_enabled) return data;    if (data.length > _paddedSize - 2) {      // Data too large to fit — chunk caller must handle; return as-is      return data;    }    final result = Uint8List(_paddedSize);    final origLen = data.length;    result[0] = (origLen >> 8) & 0xFF;    result[1] = origLen & 0xFF;    result.setRange(2, 2 + origLen, data);    // Fill rest with secure random bytes    for (var i = 2 + origLen; i < _paddedSize; i++) {      result[i] = _rng.nextInt(256);    }    return result;  }  /// Strip padding to recover original data (Req 12.5 round-trip)  Uint8List unpad(Uint8List padded) {    if (!_enabled) return padded;    if (padded.length < 2) return padded;    final origLen = (padded[0] << 8) | padded[1];    if (origLen > padded.length - 2) return padded;    return padded.sublist(2, 2 + origLen);  }  /// Apply relay delay before forwarding (Req 12.2)  Future<void> applyRelayDelay() async {    if (!_enabled) return;    final delay = _minDelayMs + _rng.nextInt(_maxDelayMs - _minDelayMs);    await Future.delayed(Duration(milliseconds: delay));  }  void _emitDummy() {    if (onSendDummy == null) return;    // Generate a random 512-byte packet that looks like a real message    final dummy = Uint8List(_paddedSize);    for (var i = 0; i < _paddedSize; i++) {      dummy[i] = _rng.nextInt(256);    }    onSendDummy!(dummy);    debugPrint('[PrivacyLayer] Dummy packet sent');  }  void dispose() {    _stopDummies();  }}